const crypto = require('crypto');

const accessKey = 'yCrnfHeNp7sKC5h3';
const secretKey = 'Em2sPDj0VaRGvnnY';
const baseUrl = 'https://metersphere.devops.moego.pet';

const timestamp = Date.now();
const uuid = crypto.randomUUID();
const comboxKey = `${accessKey}|${uuid}|${timestamp}`;

const key = Buffer.from(secretKey.slice(0, 16), 'utf-8');
const iv = Buffer.from(accessKey.slice(0, 16), 'utf-8');
const cipher = crypto.createCipheriv('aes-128-cbc', key, iv);
let encrypted = cipher.update(comboxKey, 'utf-8', 'base64');
encrypted += cipher.final('base64');

const workspaceId = '20a7019f-19aa-11ee-a261-5a66b98c4036';

return [{
  json: {
    baseUrl,
    workspaceId,
    headers: {
      'Content-Type': 'application/json',
      'ACCEPT': 'application/json',
      'accessKey': accessKey,
      'signature': encrypted
    }
  }
}];

const response = $input.first().json;

if (!response.success) {
  throw new Error(`MeterSphere API error: ${response.message}`);
}

const projects = (response.data || []).map(p => ({
  id: p.id,
  name: p.name,
  workspace_id: p.workspaceId,
  description: p.description || '',
  platform: p.platform || '',
  create_time: p.createTime ? new Date(p.createTime).toISOString() : null,
}));

return [{ json: { projects } }];
